/*
 * A103373  a(1) = a(2) = a(3) = a(4) = a(5) = a(6) = 1 and for n>6: a(n) =
 *          a(n-5) + a(n-6).
 * https://oeis.org/A103373
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = a(n-5)+a(n-6) with a(1)=a(2)=…=a(6)=1
 * Range:     u8 n <= 47, u16 n <= 91, u32 n <= 179, u64 n <= 354,
 *            u128 n <= 705, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by a linear recurrence.
   We cache the results in a dynamic array so that calls in any order
   are O(1) after the required terms have been computed once.  */

#include <stdlib.h>

seq_t a(idx_t n)
{
    static seq_t *cache = NULL;   /* cache[0] holds a(1) */
    static idx_t cached = 0;      /* number of elements cached */

    if (cached < n) {                         /* grow the cache if needed */
        seq_t *tmp = (seq_t *)realloc(cache, n * sizeof(seq_t));
        cache = tmp;

        for (idx_t i = cached; i < n; ++i) {
            if (i < 6)                       /* a(1) … a(6) = 1 */
                cache[i] = 1;
            else
                cache[i] = cache[i-5] + cache[i-6];
        }
        cached = n;
    }
    return cache[n-1];          /* n is 1‑based, array is 0‑based */
}
